package com.codexpane.companion;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.graphics.BitmapFactory;
import android.net.Uri;
import android.os.*;
import android.provider.OpenableColumns;
import android.provider.MediaStore;
import android.util.Base64;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Attachment transport is independent of turn.send. Retries never execute a task. */
final class NativeAttachments implements NativeConnection.Listener {
    interface Host {void changed();void error(String message);}
    private static final int PICK=1801,CAPTURE=1802,EXPORT=1803,CAMERA_PERMISSION=1804,CHUNK=48*1024;
    private final Activity activity;private final PaneUi ui;private final Host host;
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();
    private final NativeAttachmentCache cache;private final Set<NativeConnection> observed=new HashSet<>();
    private NativeConnection owner;private String thread="",upload="",request="",downloadId="";private JSONObject downloadMeta;
    private byte[] uploadBytes;private ByteArrayOutputStream download;private boolean closed,importing,previewDownload;
    int mediaRevision;private long uploadOffset;
    private String exportCache="",exportName="";
    private final Runnable timeout=()->fail("附件传输超时，请手动重试；不会自动发送消息");
    NativeAttachments(Activity activity,PaneUi ui,Host host){this.activity=activity;this.ui=ui;this.host=host;cache=new NativeAttachmentCache(activity);}
    private void observe(NativeConnection c){if(observed.add(c))c.add(this);}
    private JSONObject records(NativeConnection c)throws JSONException{return new JSONObject(c.local.section("attachments").toString());}
    private JSONArray drafts(NativeConnection c,String t){JSONArray out=new JSONArray();JSONObject all=c.local.section("attachments");for(Iterator<String> it=all.keys();it.hasNext();){JSONObject r=all.optJSONObject(it.next());if(r!=null&&r.optBoolean("draft")&&t.equals(r.optString("thread")))out.put(r);}return out;}
    private void change(NativeConnection c,String id,String key,Object value)throws Exception{JSONObject all=records(c);JSONObject r=all.getJSONObject(id);r.put(key,value);all.put(id,r);c.local.save("attachments",all);}
    private void busyCheck(){if(importing||owner!=null)throw new IllegalStateException("请等待当前附件处理完成，或取消后再操作");}
    void choose(NativeConnection c,String t){try{busyCheck();if(t.isEmpty())throw new IllegalStateException("请先创建或打开会话");if(!c.supports("attachmentsV1"))throw new IllegalStateException("电脑需升级至支持附件的版本");new AlertDialog.Builder(activity).setTitle("添加附件").setItems(new String[]{"选择图片","选择文件","拍照","清理已发送附件的本机缓存"},(dialog,which)->{try{if(which==3){clearCompletedCache(c);return;}rememberPicker(c,t);if(which==2){capture();return;}Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(which==0?"image/*":"*/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);activity.startActivityForResult(intent,PICK);}catch(Exception e){host.error(e.getMessage());}}).show();}catch(Exception e){host.error(e.getMessage());}}
    private SharedPreferences picker(){return activity.getSharedPreferences("attachment-picker",Context.MODE_PRIVATE);}
    private void rememberPicker(NativeConnection c,String t){if(!picker().edit().putString("computer",c.computerId).putString("thread",t).commit())throw new IllegalStateException("无法保存附件目标");}
    private void capture()throws Exception{if(activity.checkSelfPermission(android.Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{android.Manifest.permission.CAMERA},CAMERA_PERMISSION);return;}File dir=new File(activity.getCacheDir(),"attachment-capture");if(!dir.exists()&&!dir.mkdirs())throw new IOException("无法准备相机缓存");File file=new File(dir,UUID.randomUUID()+".jpg");Uri uri=androidx.core.content.FileProvider.getUriForFile(activity,activity.getPackageName()+".attachments",file);picker().edit().putString("capture",file.getName()).commit();Intent intent=new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra(MediaStore.EXTRA_OUTPUT,uri).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("photo",uri));activity.startActivityForResult(intent,CAPTURE);}
    boolean onRequestPermissionsResult(int code,String[] permissions,int[] results){if(code!=CAMERA_PERMISSION)return false;if(results.length==0||results[0]!=android.content.pm.PackageManager.PERMISSION_GRANTED){host.error("未允许相机，可改用选择图片");return true;}try{capture();}catch(Exception e){host.error("无法打开相机");}return true;}
    boolean onActivityResult(int code,int result,Intent data){if(code!=PICK&&code!=CAPTURE&&code!=EXPORT)return false;if(code==EXPORT){if(result==Activity.RESULT_OK&&data!=null&&data.getData()!=null&&"content".equals(data.getData().getScheme())&&!exportCache.isEmpty()){final Uri uri=data.getData();final String id=exportCache;io.execute(()->{try{byte[] bytes=cache.read(id);try(OutputStream out=activity.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();out.write(bytes);}main.post(()->{if(!closed)Toast.makeText(activity,"文件已保存",Toast.LENGTH_SHORT).show();});}catch(Exception e){report("文件保存失败");}});}exportCache="";return true;}
        String computer=picker().getString("computer",""),target=picker().getString("thread","");NativeConnection c=NativeConnections.get(activity).find(computer);if(c==null){host.error("附件所属电脑已移除");return true;}if(result!=Activity.RESULT_OK){cleanupCapture();return true;}
        ArrayList<Uri> uris=new ArrayList<>();if(code==CAPTURE){String name=picker().getString("capture","");if(name.matches("[0-9a-fA-F-]{36}\\.jpg"))uris.add(Uri.fromFile(new File(new File(activity.getCacheDir(),"attachment-capture"),name)));}else if(data!=null){if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount()&&i<9;i++){Uri selected=data.getClipData().getItemAt(i).getUri();if("content".equals(selected.getScheme()))uris.add(selected);}}else if(data.getData()!=null&&"content".equals(data.getData().getScheme()))uris.add(data.getData());}
        if(uris.size()+drafts(c,target).length()>8){host.error("每条消息最多 8 个附件");cleanupCapture();return true;}importing=true;host.changed();io.execute(()->{try{for(Uri uri:uris)importOne(c,target,uri);}finally{main.post(()->{importing=false;cleanupCapture();if(!closed)host.changed();});}});return true;
    }
    private void cleanupCapture(){String name=picker().getString("capture","");if(name.matches("[0-9a-fA-F-]{36}\\.jpg"))new File(new File(activity.getCacheDir(),"attachment-capture"),name).delete();picker().edit().remove("capture").apply();}
    private void importOne(NativeConnection c,String t,Uri uri){String id=UUID.randomUUID().toString();try{String name="附件",mime=activity.getContentResolver().getType(uri);if("file".equals(uri.getScheme())){name="拍摄照片.jpg";mime="image/jpeg";}else try(Cursor cursor=activity.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){name=cursor.getString(0);if(!cursor.isNull(1)&&cursor.getLong(1)>NativeAttachmentCache.MAX_BYTES)throw new IOException("附件超过 20 MiB");}}
            name=safeName(name);if(mime==null||!mime.matches("[A-Za-z0-9.+-]+/[A-Za-z0-9.+-]+"))mime="application/octet-stream";byte[] bytes;try(InputStream input=activity.getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("无法读取文件");bytes=NativeAttachmentCache.bounded(input);}cache.save(id,bytes);JSONObject r=NativeConnection.obj("uploadId",id,"cacheId",id,"thread",t,"draft",true,"name",name,"mime",mime,"size",bytes.length,"sha256",NativeAttachmentCache.hash(bytes),"offset",0,"state","待上传");
            main.post(()->{try{if(NativeConnections.get(activity).find(c.computerId)!=c){cache.remove(id);return;}JSONObject all=records(c);all.put(id,r);c.local.save("attachments",all);if(!closed)host.changed();}catch(Exception e){cache.remove(id);if(!closed)host.error("附件草稿保存失败");}});
        }catch(Exception e){cache.remove(id);report(e.getMessage()==null?"附件读取失败":e.getMessage());}}
    static String safeName(String value){String name=value==null?"附件":value.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_").trim().replaceAll("[. ]+$","");if(name.isEmpty())name="附件";if(name.length()>170)name=name.substring(name.length()-170);if(name.matches("(?i)^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\\..*)?$"))name="_"+name;return name;}
    private void clearCompletedCache(NativeConnection c)throws Exception{JSONObject all=records(c);for(Iterator<String> it=all.keys();it.hasNext();){JSONObject r=all.optJSONObject(it.next());if(r!=null&&!r.optBoolean("draft")&&!r.optString("cacheId").isEmpty()){JSONObject receipt=c.local.section("requests").optJSONObject(r.optString("requestId"));if(receipt!=null&&"completed".equals(receipt.optString("status"))&&r.optJSONObject("attachment")!=null&&available(c,r.optString("thread"),r.optJSONObject("attachment"))){cache.remove(r.optString("cacheId"));r.put("cacheId","");}}}c.local.save("attachments",all);JSONObject links=new JSONObject(c.local.section("attachmentDownloads").toString());ArrayList<String> clear=new ArrayList<>();for(Iterator<String> it=links.keys();it.hasNext();){String key=it.next();JSONObject r=links.optJSONObject(key);if(r!=null&&!"true".equals(c.local.text("attachmentDeleted",key))&&!r.optString("cacheId").isEmpty()){cache.remove(r.optString("cacheId"));clear.add(key);}}for(String key:clear)links.remove(key);c.local.save("attachmentDownloads",links);mediaRevision++;host.changed();}
    private void report(String text){main.post(()->{if(!closed)host.error(text);});}
    void renderDrafts(LinearLayout parent,NativeConnection c,String t){
        observe(c);JSONArray items=drafts(c,t);StringBuilder identity=new StringBuilder(c.computerId+":"+t+":"+importing);boolean clean=false;JSONObject records=c.local.section("attachments");
        for(int i=0;i<items.length();i++){JSONObject r=items.optJSONObject(i);identity.append('|').append(r.optString("uploadId")).append(':').append(r.has("attachment"));}
        for(Iterator<String> it=records.keys();it.hasNext();){JSONObject r=records.optJSONObject(it.next());if(r!=null&&r.optBoolean("pendingDelete")&&t.equals(r.optString("thread")))clean=true;}identity.append(clean);
        boolean rebuild=!identity.toString().equals(parent.getTag());
        if(rebuild){parent.removeAllViews();parent.setTag(identity.toString());if(importing)parent.addView(ui.text("正在加密保存附件…",12,PaneUi.MUTED));}
        for(int i=0;i<items.length();i++){
            JSONObject r=items.optJSONObject(i);String id=r.optString("uploadId"),status=r.has("attachment")?"已上传，等待发送":r.optString("state","待上传");if(owner==c&&id.equals(upload)&&uploadBytes!=null)status="上传中 "+(uploadOffset*100/uploadBytes.length)+"%";else if(!r.has("attachment")&&(status.startsWith("准备上传")||status.startsWith("上传中")))status="等待上传 / 重试";TextView label=parent.findViewWithTag("label:"+id);Button transfer=parent.findViewWithTag("transfer:"+id);
            if(rebuild){LinearLayout row=ui.row();ui.pad(row,12,4);label=ui.text("",12,PaneUi.INK);label.setTag("label:"+id);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));if(!r.has("attachment")){transfer=ui.button("上传 / 重试",PaneUi.BG,PaneUi.BLUE,()->{if(owner==c&&id.equals(upload))fail("上传已暂停，可手动重试");else startUpload(c,t,id);});transfer.setTag("transfer:"+id);row.addView(transfer);}row.addView(ui.iconButton("close","移除附件",()->remove(c,id)));parent.addView(row);if(r.optString("mime").startsWith("image/"))thumbnail(parent,r.optString("cacheId"),()->previewLocal(c,t,r));}
            if(label!=null)label.setText(r.optString("name")+" · "+size(r.optLong("size"))+"\n"+status);if(transfer!=null)transfer.setText(owner==c&&id.equals(upload)?"取消":"上传 / 重试");
        }
        if(rebuild&&clean)parent.addView(ui.button("清理已移除的电脑端附件",PaneUi.BG,PaneUi.BLUE,()->cleanup(c,t)));
    }
    private String size(long bytes){return bytes>=1024*1024?String.format(Locale.ROOT,"%.1f MiB",bytes/1048576d):Math.max(1,bytes/1024)+" KiB";}
    private void remove(NativeConnection c,String id){try{if(owner==c&&id.equals(upload))reset();JSONObject all=records(c);JSONObject r=all.optJSONObject(id);if(r==null)return;r.put("draft",false);r.put("pendingDelete",true);all.put(id,r);c.local.save("attachments",all);if(!r.optString("cacheId").isEmpty())cache.remove(r.optString("cacheId"));cleanup(c,r.optString("thread"));host.changed();}catch(Exception e){host.error("无法移除附件");}}
    private void cleanup(NativeConnection c,String t){if(owner!=null||!c.authenticated||!t.equals(c.snapshot.optString("activeThreadId")))return;JSONObject all=c.local.section("attachments");for(Iterator<String> it=all.keys();it.hasNext();){String id=it.next();JSONObject r=all.optJSONObject(id);if(r!=null&&r.optBoolean("pendingDelete")&&t.equals(r.optString("thread"))){try{owner=c;thread=t;upload=id;observe(c);send(NativeConnection.obj("type","attachment.cancel","threadId",t,"uploadId",id));}catch(Exception e){fail(e.getMessage());}return;}}}
    JSONArray attachmentIds(NativeConnection c,String t)throws Exception{if(importing)throw new IllegalStateException("附件正在保存，请稍候");JSONArray ids=new JSONArray(),items=drafts(c,t);for(int i=0;i<items.length();i++){JSONObject a=items.getJSONObject(i).optJSONObject("attachment");if(a==null)throw new IllegalStateException("请先完成附件上传");ids.put(a.getString("id"));}JSONArray requests=c.requests(t);for(int i=0;i<requests.length();i++){JSONObject r=requests.getJSONObject(i);if(Arrays.asList("waiting","accepted","unknown").contains(r.optString("status"))){JSONArray sent=r.optJSONArray("attachmentIds");if(sent!=null)for(int j=0;j<sent.length();j++)for(int k=0;k<ids.length();k++)if(sent.optString(j).equals(ids.optString(k)))throw new IllegalStateException("附件已有待核对发送记录，请先核对，避免重复执行");}}return ids;}
    void sent(NativeConnection c,String t,String requestId)throws Exception{JSONObject all=records(c);JSONArray items=drafts(c,t);for(int i=0;i<items.length();i++){JSONObject r=items.getJSONObject(i);r.put("draft",false);r.put("requestId",requestId);all.put(r.getString("uploadId"),r);}c.local.save("attachments",all);mediaRevision++;host.changed();}
    static boolean canRestoreRequest(JSONObject receipt){return receipt!=null&&"failed".equals(receipt.optString("status"))&&(receipt.optString("manualResolution").isEmpty()||"notExecuted".equals(receipt.optString("manualResolution")));}
    void restoreRequestDraft(NativeConnection c,String requestId)throws Exception{
        JSONObject receipt=c.local.section("requests").optJSONObject(requestId);if(!canRestoreRequest(receipt))throw new IllegalStateException("只能恢复确认失败或已核对未执行的附件，待核对请求不能重发");
        String t=receipt.optString("threadId");JSONArray ids=receipt.optJSONArray("attachmentIds");if(ids==null||ids.length()==0)throw new IllegalStateException("该记录没有附件");JSONObject all=records(c);ArrayList<JSONObject> restore=new ArrayList<>();
        for(int i=0;i<ids.length();i++){JSONObject found=null;for(Iterator<String> it=all.keys();it.hasNext();){JSONObject r=all.optJSONObject(it.next());JSONObject a=r==null?null:r.optJSONObject("attachment");if(r!=null&&a!=null&&t.equals(r.optString("thread"))&&ids.optString(i).equals(a.optString("id")))found=r;}if(found==null||found.optBoolean("pendingDelete")||!cache.exists(found.optString("cacheId")))throw new IllegalStateException("部分附件本机缓存已不存在，请重新选择原文件");restore.add(found);}
        int count=drafts(c,t).length();for(JSONObject r:restore)if(!r.optBoolean("draft"))count++;if(count>8)throw new IllegalStateException("当前草稿加恢复附件超过 8 项，请先整理草稿");
        for(JSONObject r:restore){r.put("draft",true);r.put("state","已恢复草稿；需明确点击发送");all.put(r.getString("uploadId"),r);}c.local.save("attachments",all);mediaRevision++;host.changed();
    }
    private void startUpload(NativeConnection c,String t,String id){try{busyCheck();if(!c.supports("attachmentsV1"))throw new IllegalStateException("电脑不支持附件");JSONObject r=records(c).getJSONObject(id);owner=c;thread=t;upload=id;observe(c);change(c,id,"state","准备上传…");host.changed();io.execute(()->{try{byte[] bytes=cache.read(r.getString("cacheId"));if(!NativeAttachmentCache.hash(bytes).equals(r.getString("sha256")))throw new IOException("本机附件校验失败");main.post(()->{if(closed||owner!=c||!id.equals(upload))return;uploadBytes=bytes;try{send(NativeConnection.obj("type","attachment.begin","threadId",t,"uploadId",id,"name",r.getString("name"),"mime",r.getString("mime"),"size",r.getLong("size"),"sha256",r.getString("sha256")));}catch(Exception e){fail(e.getMessage());}});}catch(Exception e){main.post(()->fail(e.getMessage()));}});}catch(Exception e){fail(e.getMessage());}}
    private void send(JSONObject command)throws Exception{if(owner==null||!thread.equals(owner.snapshot.optString("activeThreadId")))throw new IllegalStateException("会话已切换，附件传输暂停");request=owner.command(command);main.removeCallbacks(timeout);main.postDelayed(timeout,30000);}
    @Override public void changed(JSONObject event){if(owner==null||!owner.computerId.equals(event.optString("computerId")))return;if("connection".equals(event.optString("type"))&&!owner.authenticated){fail("连接中断，可手动重试附件传输");return;}if(!request.equals(event.optString("requestId")))return;String type=event.optString("type");try{if("command.result".equals(type)){if(!event.optBoolean("ok"))fail(event.optString("message","附件操作失败"));return;}if(!thread.equals(event.optString("threadId")))throw new SecurityException("附件会话不匹配");main.removeCallbacks(timeout);
            if("attachment.deleted".equals(type)&&downloadId.equals(event.optString("attachmentId"))){owner.local.text("attachmentDeleted",thread+":"+downloadId,"true");reset();mediaRevision++;host.changed();return;}
            if("attachment.status".equals(type)&&upload.equals(event.optString("uploadId"))){if(event.optBoolean("cancelled")){JSONObject all=records(owner);JSONObject removed=all.optJSONObject(upload);all.remove(upload);owner.local.save("attachments",all);if(removed!=null&&!removed.optString("cacheId").isEmpty())cache.remove(removed.optString("cacheId"));reset();host.changed();return;}long offset=event.getLong("offset");if(uploadBytes==null||offset<0||offset>uploadBytes.length)throw new IOException("附件偏移无效");uploadOffset=offset;if(event.optBoolean("complete")){JSONObject attachment=event.getJSONObject("attachment"),r=records(owner).getJSONObject(upload);validate(attachment);if(!r.getString("sha256").equals(attachment.getString("sha256"))||r.getLong("size")!=attachment.getLong("size"))throw new IOException("电脑附件校验不一致");change(owner,upload,"attachment",attachment);change(owner,upload,"state","已上传，等待发送");mediaRevision++;reset();host.changed();return;}host.changed();if(offset==uploadBytes.length)send(NativeConnection.obj("type","attachment.finish","threadId",thread,"uploadId",upload));else{int end=Math.min(uploadBytes.length,(int)offset+CHUNK);send(NativeConnection.obj("type","attachment.chunk","threadId",thread,"uploadId",upload,"offset",offset,"data",Base64.encodeToString(Arrays.copyOfRange(uploadBytes,(int)offset,end),Base64.NO_WRAP)));}}
            else if("attachment.chunk".equals(type)&&downloadId.equals(event.optString("attachmentId"))){if(event.getLong("offset")!=download.size())throw new IOException("下载顺序无效");String encoded=event.getString("data");if(encoded.length()>CHUNK*4/3+8)throw new IOException("附件块过大");byte[] bytes=Base64.decode(encoded,Base64.DEFAULT);if(bytes.length>CHUNK||download.size()+bytes.length>downloadMeta.getLong("size"))throw new IOException("附件长度无效");download.write(bytes);if(event.optBoolean("eof")){byte[] full=download.toByteArray();if(full.length!=downloadMeta.getLong("size")||!NativeAttachmentCache.hash(full).equals(downloadMeta.getString("sha256")))throw new IOException("下载完整性校验失败");JSONObject meta=downloadMeta;String id=UUID.randomUUID().toString();NativeConnection c=owner;String t=thread;boolean show=previewDownload;reset();io.execute(()->{try{cache.save(id,full);main.post(()->{try{if(NativeConnections.get(activity).find(c.computerId)!=c){cache.remove(id);return;}JSONObject links=new JSONObject(c.local.section("attachmentDownloads").toString());links.put(t+":"+meta.getString("id"),NativeConnection.obj("cacheId",id,"sha256",meta.getString("sha256")));c.local.save("attachmentDownloads",links);mediaRevision++;if(!closed){host.changed();if(show)showFile(c,t,meta,id,full);}}catch(Exception e){host.error("附件缓存记录失败");}});}catch(Exception e){report(e.getMessage());}});}else{if(bytes.length==0)throw new IOException("下载没有进展");send(NativeConnection.obj("type","attachment.read","threadId",thread,"attachmentId",downloadId,"offset",download.size()));}}
        }catch(Exception e){fail(e.getMessage());}}
    private void reset(){main.removeCallbacks(timeout);if(owner!=null)owner.forgetAttachmentRequest(request);owner=null;uploadOffset=0;thread="";upload="";request="";uploadBytes=null;download=null;downloadMeta=null;downloadId="";}
    private void fail(String message){try{if(owner!=null&&!upload.isEmpty())change(owner,upload,"state",message==null?"传输失败，请重试":message);}catch(Exception ignored){}reset();if(!closed){host.changed();host.error(message==null?"附件操作失败":message);}}
    static void validate(JSONObject a)throws Exception{UUID.fromString(a.getString("id"));long size=a.getLong("size");if(size<1||size>NativeAttachmentCache.MAX_BYTES||!a.getString("sha256").matches("[0-9a-f]{64}"))throw new IOException("附件元数据无效");}
    private String cached(NativeConnection c,String t,JSONObject meta){JSONObject links=c.local.section("attachmentDownloads").optJSONObject(t+":"+meta.optString("id"));if(links!=null&&meta.optString("sha256").equals(links.optString("sha256")))return links.optString("cacheId");JSONObject all=c.local.section("attachments");for(Iterator<String> it=all.keys();it.hasNext();){JSONObject r=all.optJSONObject(it.next());JSONObject a=r==null?null:r.optJSONObject("attachment");if(a!=null&&t.equals(r.optString("thread"))&&meta.optString("id").equals(a.optString("id")))return r.optString("cacheId");}return "";}
    private void thumbnail(LinearLayout parent,String id,Runnable open){ImageView image=new ImageView(activity);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);image.setBackground(ui.rounded(PaneUi.BG,12));image.setContentDescription("附件缩略图，点击放大");image.setTag(id);image.setOnClickListener(v->open.run());parent.addView(image,new LinearLayout.LayoutParams(-1,ui.dp(140)));io.execute(()->{try{byte[] bytes=cache.read(id);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=1;while(o.outWidth/o.inSampleSize>600||o.outHeight/o.inSampleSize>600)o.inSampleSize*=2;o.inJustDecodeBounds=false;android.graphics.Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);main.post(()->{if(!closed&&id.equals(image.getTag()))image.setImageBitmap(bitmap);});}catch(Exception ignored){}});}
    private void previewLocal(NativeConnection c,String t,JSONObject record){String id=record.optString("cacheId");JSONObject meta=record.optJSONObject("attachment");if(meta==null)meta=NativeConnection.obj("name",record.optString("name"),"mime",record.optString("mime"),"size",record.optLong("size"),"kind",record.optString("mime").startsWith("image/")?"image":"file");JSONObject m=meta;io.execute(()->{try{byte[] bytes=cache.read(id);main.post(()->{if(!closed)showFile(c,t,m,id,bytes);});}catch(Exception e){report("本机附件缓存不可用");}});}
    private boolean available(NativeConnection c,String t,JSONObject a){return a.optBoolean("available",true)&&!"true".equals(c.local.text("attachmentDeleted",t+":"+a.optString("id")));}
    void appendMessage(LinearLayout parent,JSONArray attachments,NativeConnection c,String t){if(attachments==null)return;for(int i=0;i<Math.min(8,attachments.length());i++){JSONObject a=attachments.optJSONObject(i);if(a==null)continue;String local=cached(c,t,a);boolean image="image".equals(a.optString("kind")),remote=available(c,t,a);if(image&&!local.isEmpty())thumbnail(parent,local,()->open(c,t,a));Button button=ui.button((image?"图片 · ":"附件 · ")+a.optString("name")+" · "+size(a.optLong("size"))+(!remote?" · 电脑副本已删除":local.isEmpty()?" · 点击加载":""),PaneUi.BG,PaneUi.BLUE,()->open(c,t,a));button.setContentDescription("查看附件 "+a.optString("name"));button.setEnabled(remote||!local.isEmpty());parent.addView(button);Button delete=ui.button(remote?"删除电脑附件副本":"重试清理电脑副本",PaneUi.BG,PaneUi.MUTED,()->confirmRemoteDelete(c,t,a));delete.setEnabled(!c.readOnly());delete.setAlpha(c.readOnly()?.4f:1f);parent.addView(delete);}}
    private void confirmRemoteDelete(NativeConnection c,String t,JSONObject meta){new AlertDialog.Builder(activity).setTitle("删除电脑附件副本？").setMessage(meta.optString("name")+"\n删除后聊天历史将无法从电脑下载此文件；本机已经缓存的副本不受影响。此操作不能恢复，需重新上传原文件。不会删除工作区其他文件。").setNegativeButton("取消",null).setPositiveButton("确认删除",(dialog,which)->{try{busyCheck();if(!t.equals(c.snapshot.optString("activeThreadId"))||Arrays.asList("running","waiting").contains(c.snapshot.optString("turnStatus")))throw new IllegalStateException("请在该会话空闲后删除附件");JSONArray records=c.requests(t);for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);if(!Arrays.asList("waiting","accepted","unknown").contains(r.optString("status")))continue;JSONArray ids=r.optJSONArray("attachmentIds");if(ids!=null)for(int j=0;j<ids.length();j++)if(meta.optString("id").equals(ids.optString(j)))throw new IllegalStateException("附件仍有关联请求待核对，不能删除");}owner=c;thread=t;downloadId=meta.getString("id");observe(c);send(NativeConnection.obj("type","attachment.delete","threadId",t,"attachmentId",downloadId));}catch(Exception e){fail(e.getMessage());}}).show();}
    private void open(NativeConnection c,String t,JSONObject meta){try{busyCheck();validate(meta);String local=cached(c,t,meta);if(!local.isEmpty()){io.execute(()->{try{byte[] full=cache.read(local);if(!NativeAttachmentCache.hash(full).equals(meta.getString("sha256")))throw new IOException();main.post(()->{if(!closed)showFile(c,t,meta,local,full);});}catch(Exception e){main.post(()->{try{JSONObject links=new JSONObject(c.local.section("attachmentDownloads").toString());links.remove(t+":"+meta.optString("id"));c.local.save("attachmentDownloads",links);JSONObject all=records(c);for(Iterator<String> it=all.keys();it.hasNext();){JSONObject r=all.optJSONObject(it.next());if(r!=null&&local.equals(r.optString("cacheId")))r.put("cacheId","");}c.local.save("attachments",all);mediaRevision++;if(!closed)open(c,t,meta);}catch(Exception ignored){report("附件缓存恢复失败");}});}});return;}if(!available(c,t,meta))throw new IllegalStateException("电脑附件副本已删除，本机也没有缓存");owner=c;thread=t;downloadId=meta.getString("id");downloadMeta=meta;previewDownload=true;download=new ByteArrayOutputStream();observe(c);host.changed();send(NativeConnection.obj("type","attachment.read","threadId",t,"attachmentId",downloadId,"offset",0));Toast.makeText(activity,"正在下载并校验附件…",Toast.LENGTH_SHORT).show();}catch(Exception e){fail(e.getMessage());}}
    private void showFile(NativeConnection c,String t,JSONObject meta,String cacheId,byte[] bytes){LinearLayout content=ui.column();ui.pad(content,16,12);content.addView(ui.heading(meta.optString("name"),17));if("image".equals(meta.optString("kind"))){try{content.addView(new NativeAttachmentImage(activity,bytes),new LinearLayout.LayoutParams(-1,0,1));}catch(Exception e){content.addView(ui.text("图片无法预览，仍可保存原文件",14,PaneUi.MUTED));}}else content.addView(ui.text(size(meta.optLong("size"))+" · "+meta.optString("mime")+"\n文件已通过完整性校验。",14,PaneUi.MUTED));Dialog dialog=new Dialog(activity,android.R.style.Theme_Material_Light_NoActionBar);content.setFitsSystemWindows(true);dialog.setContentView(content);content.addView(ui.button("关闭预览",PaneUi.BG,PaneUi.BLUE,dialog::dismiss));content.addView(ui.button("保存到文件",PaneUi.BG,PaneUi.BLUE,()->{exportCache=cacheId;exportName=meta.optString("name","附件");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(meta.optString("mime","application/octet-stream")).putExtra(Intent.EXTRA_TITLE,exportName);activity.startActivityForResult(intent,EXPORT);}));content.addView(ui.button("分享文件",PaneUi.BG,PaneUi.BLUE,()->share(meta,bytes)));dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,-1);}
    private void share(JSONObject meta,byte[] bytes){io.execute(()->{try{File dir=new File(activity.getCacheDir(),"attachment-exports");if(!dir.exists()&&!dir.mkdirs())throw new IOException();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(System.currentTimeMillis()-f.lastModified()>3600000)f.delete();String safe=safeName(meta.optString("name","附件"));File file=new File(dir,UUID.randomUUID()+"-"+safe);try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}Uri uri=androidx.core.content.FileProvider.getUriForFile(activity,activity.getPackageName()+".attachments",file);main.post(()->{if(closed)return;Intent intent=new Intent(Intent.ACTION_SEND).setType(meta.optString("mime","application/octet-stream")).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("attachment",uri));activity.startActivity(Intent.createChooser(intent,"分享附件"));});}catch(Exception e){report("无法分享附件");}});}
    void close(){closed=true;reset();for(NativeConnection c:observed)c.remove(this);observed.clear();main.removeCallbacksAndMessages(null);io.shutdown();}
}
